// D-BD-r5 probe (B.3): the body-scale defence read at WC §1.8.1's read-point defenseLedger(settlement),
// on settlements GENERATED by master's own pipeline (seeded, headless), per tier x seed.
const M = '/private/tmp/claude-502/-Users-cstokes-Desktop-settlement-engine/a73343ed-904d-46d0-a0f5-2969909eb66e/scratchpad/master-81f1cd963/src';
const { generateSettlementPipeline } = await import(M + '/generators/generateSettlementPipeline.js');
const { defenseLedger } = await import(M + '/domain/defenseLedger.js');
const tiers = ['thorp', 'hamlet', 'village', 'town', 'city', 'metropolis'];
const terrains = ['plains', 'forest', 'hills', 'riverside'];
const rows = [];
for (const tier of tiers) {
  for (let i = 0; i < 12; i++) {
    const terrainOverride = terrains[i % terrains.length];
    const s = generateSettlementPipeline({ settType: tier, culture: 'germanic', terrainOverride, tradeRouteAccess: 'road' }, null, { seed: `bd-r5-def-${tier}-${i}`, customContent: {} });
    const L = defenseLedger(s);
    const names = (s.institutions || []).map(x => String(x?.name || '')).join('|').toLowerCase();
    const walls = /wall|palisade|rampart|fortif|citadel|keep/.test(names);
    rows.push({ tier, i, terrainOverride, military: L.military, monster: L.monster, internal: L.internal, walls, present: L.present });
  }
}
const stat = (a) => { const s = [...a].sort((x, y) => x - y); return `min ${s[0]} med ${s[Math.floor(s.length / 2)]} max ${s[s.length - 1]}`; };
for (const tier of tiers) {
  const r = rows.filter(x => x.tier === tier);
  console.log(tier.padEnd(11), 'military', stat(r.map(x => x.military)).padEnd(24), '| monster', stat(r.map(x => x.monster)).padEnd(24), '| internal', stat(r.map(x => x.internal)).padEnd(24), '| walled', r.filter(x => x.walls).length + '/' + r.length, '| present', r.every(x => x.present));
}
import { writeFileSync } from 'node:fs';
writeFileSync(new URL('./defence-ledger.rows.json', import.meta.url), JSON.stringify(rows, null, 1));
